+  margin: 14px 0 10px;
+  color: var(--muted);
+}
+
+.sub-label {
+  margin-top: 10px;
+  color: var(--muted);
+  font-size: 0.92rem;
+}
+
+.list {
+  margin: 0;
+  padding-left: 18px;
+  color: var(--muted);
+}
+
+.stats {
+  display: grid;
+  grid-template-columns: repeat(2, minmax(0, 1fr));
+  gap: 12px;
+}
+
+.stat {
+  border: 1px solid var(--border);
+  border-radius: 14px;
+  background: var(--surface-2);
+  padding: 14px;
+}
+
+.stat strong {
+  display: block;
+  font-size: 1.2rem;
+  color: var(--navy);
+}
+
+.stat span {
+  color: var(--muted);
+  font-size: 0.92rem;
+}
+
+/* Accordion */
+.accordion {
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  overflow: hidden;
+  background: var(--surface);
+}
+
+.acc-item + .acc-item {
+  border-top: 1px solid var(--border);
+}
+
+.acc-btn {
+  width: 100%;
+  text-align: left;
+  padding: 14px 16px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 14px;
+  border: 0;
+  background: transparent;
+  cursor: pointer;
+  font-weight: 800;
+  color: var(--navy);
+}
+
+.acc-btn span {
+  color: var(--muted);
+  font-weight: 700;
+}
+
+.acc-panel {
+  max-height: 0;
+  overflow: hidden;
+  transition: max-height 260ms ease;
+}
+
+.acc-panel-inner {
+  padding: 0 16px 14px;
+  color: var(--muted);
+}
+
+.acc-item[data-open="true"] .acc-panel {
+  max-height: 240px;
+}
+
+/* Popular tags */
+.tag-row {
+  display: flex;
+  gap: 10px;
+  overflow-x: auto;
+  padding-bottom: 6px;
+}
+
+.tag-chip {
+  flex: 0 0 auto;
+  display: inline-flex;
+  gap: 10px;
+  align-items: center;
+  padding: 10px 12px;
+  border-radius: 999px;
+  border: 1px solid var(--border);
+  background: var(--surface-2);
+  color: var(--navy);
+  font-weight: 750;
+  white-space: nowrap;
+}
+
+.tag-chip small {
+  color: var(--muted);
+  font-weight: 700;
+}
+
+/* Footer */
+footer {
+  border-top: 1px solid var(--border);
+  background: #fff;
+}
+
+.footer-inner {
+  padding: 28px 0;
+  display: grid;
+  grid-template-columns: 1.4fr 1fr;
+  gap: 18px;
+}
+
+.footer-inner h3 {
+  margin: 0 0 10px;
+  font-size: 1rem;
+  letter-spacing: -0.01em;
+}
+
+.footer-inner p {
+  margin: 0;
+  color: var(--muted);
+}
+
+.pill-links {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 8px;
+}
+
+.pill-links a {
+  border: 1px solid var(--border);
+  padding: 8px 10px;
+  border-radius: 999px;
+  background: var(--surface-2);
+  color: var(--navy);
+  font-weight: 650;
+  font-size: 0.92rem;
+}
+
+/* Responsive */
+@media (max-width: 980px) {
+  .header-inner {
+    grid-template-columns: 1fr auto;
+  }
+
+  .search {
+    display: none;
+  }
+
+  .nav {
+    display: none;
+  }
+
+  .menu-btn {
+    display: inline-flex;
+    align-items: center;
+    gap: 10px;
+  }
+
+  .featured {
+    grid-template-columns: 1fr;
+  }
+
+  .donate-hero {
+    grid-template-columns: 1fr;
+  }
+
+  .syllabus-grid {
+    grid-template-columns: 1fr;
+  }
+
+  .grid.cols-3 {
+    grid-template-columns: 1fr;
+  }
+
+  .grid.cols-2 {
+    grid-template-columns: 1fr;
+  }
+}
+
*** End Patch
PATCH

